import os,json,pathlib,urllib.request,base64,hashlib,tempfile,subprocess,shutil,sys
root=pathlib.Path('/home/appontrack/public_html/ayo')
backup=pathlib.Path('/home/appontrack/.ayo-voice-gateway-v12-backup-20261105')
want=json.loads(sys.argv[1])
allowed={'app.js','index.php','style.css','api.php'}
if set(want)!=allowed or backup.exists() or not root.is_dir() or root.is_symlink():raise RuntimeError('unexpected scope or existing backup')
config=json.loads(pathlib.Path('/home/appontrack/ontrack-voice-link/config.json').read_text())
headers={'Authorization':'Bearer '+config['token'],'Accept':'application/vnd.github+json','User-Agent':'OnTrack-AYO-SHA-Publisher'}
data={}
for name,sha in want.items():
 url='https://api.github.com/repos/OnTrack-Development/OnTrack-voice/contents/ayo/'+name+'?ref=feat/ayo-php-host-demo-20261105'
 with urllib.request.urlopen(urllib.request.Request(url,headers=headers),timeout=8) as r:v=json.load(r)
 raw=base64.b64decode(v['content'])
 digest=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()
 if sha!=v['sha'] or sha!=digest:raise RuntimeError('file integrity mismatch '+name)
 data[name]=raw
php=shutil.which('php') or '/usr/local/bin/php'
with tempfile.TemporaryDirectory(dir='/home/appontrack') as tmp:
 p=pathlib.Path(tmp)
 for name,raw in data.items():(p/name).write_bytes(raw)
 for name in ('index.php','api.php'):
  lint=subprocess.run([php,'-l',str(p/name)],capture_output=True,text=True,timeout=7)
  if lint.returncode:raise RuntimeError('PHP lint failed '+name)
 node=shutil.which('node')
 if node:
  f=p/'app.js'
  source=f.read_text().replace("import { createAyoAvatar } from './ayo-avatar.js';","").replace("import { createMicTurns } from './ayo-mic-stt.js';","")
  check=p/'app-check.js';check.write_text(source)
  result=subprocess.run([node,'--check',str(check)],capture_output=True,text=True,timeout=6)
  if result.returncode:raise RuntimeError('JS syntax invalid')
backup.mkdir(mode=0o700)
for name in allowed:
 f=root/name
 if not f.is_file() or f.is_symlink():raise RuntimeError('missing or symlink '+name)
 (backup/name).write_bytes(f.read_bytes())
installed=[]
try:
 for name,raw in data.items():
  target=root/name;staging=root/(name+'.ayo-v12')
  fd=os.open(staging,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o644)
  with os.fdopen(fd,'wb') as f:f.write(raw)
  os.chmod(staging,0o644);os.replace(staging,target)
  installed.append(name)
except:
 for name in installed:
  (root/name).write_bytes((backup/name).read_bytes());os.chmod(root/name,0o644)
 raise
print(json.dumps({'deployed':True,'scope':'ayo only','files':sorted(installed),'sha256_check':'gitblob matched','lint':'passed','backup_outside_site':True,'version':'v12'}))
